-- Section 2: make existing manual move/swap RPCs atomically block-aware.
create or replace function public.get_schedule_block_move_plan_v1(p_schedule_id uuid,p_weekday smallint,p_period smallint,p_classroom_id uuid default null) returns jsonb language plpgsql security definer set search_path=public as $$declare r public.teacher_schedule%rowtype;v_pattern smallint[];v_len int;v_start int;v_target_start int;v_moves jsonb;v_periods int;begin perform public.open_permission_context('schedule.edit');select * into r from public.teacher_schedule where id=p_schedule_id and active and institution_code=public.current_tenant_code();if not found then return jsonb_build_object('ok',false,'error','SCHEDULE_ROW_NOT_FOUND');end if;if r.locked then return jsonb_build_object('ok',false,'error','SCHEDULE_ROW_LOCKED');end if;if r.teacher_assignment_id is null then return jsonb_build_object('ok',false,'error','SCHEDULE_SEMANTIC_LINK_REQUIRED');end if;select public.normalize_schedule_block_pattern_v2(er.block_pattern,a.assigned_hours) into v_pattern from public.teacher_course_assignments a cross join lateral public.get_effective_schedule_rule_v2(a.class_course_requirement_id,a.id) er where a.id=r.teacher_assignment_id and a.institution_code=public.current_tenant_code();if coalesce((select max(x) from unnest(v_pattern)x),1)<=1 then return jsonb_build_object('ok',false,'error','NOT_BLOCK_ACTIVITY');end if;with ordered as(select ts.id,ts.period,ts.period-row_number() over(order by ts.period)::integer grp from public.teacher_schedule ts where ts.active and ts.institution_code=public.current_tenant_code() and ts.teacher_assignment_id=r.teacher_assignment_id and ts.weekday=r.weekday),target as(select grp from ordered where id=p_schedule_id) select min(o.period),count(*)::int into v_start,v_len from ordered o join target t on t.grp=o.grp;if v_len is null or not(v_len=any(v_pattern)) then return jsonb_build_object('ok',false,'error','BLOCK_COMPONENT_UNRESOLVED');end if;v_target_start:=p_period-(r.period-v_start);select periods_per_day into v_periods from public.get_active_schedule_time_profile();if v_target_start<1 or v_target_start+v_len-1>v_periods then return jsonb_build_object('ok',false,'error','BLOCK_TARGET_OUT_OF_RANGE');end if;if exists(select 1 from public.teacher_schedule x where x.active and x.institution_code=public.current_tenant_code() and x.teacher_assignment_id=r.teacher_assignment_id and x.weekday=p_weekday and x.period in(v_target_start-1,v_target_start+v_len) and x.id not in(with ordered as(select ts.id,ts.period,ts.period-row_number() over(order by ts.period)::integer grp from public.teacher_schedule ts where ts.active and ts.institution_code=public.current_tenant_code() and ts.teacher_assignment_id=r.teacher_assignment_id and ts.weekday=r.weekday),target as(select grp from ordered where id=p_schedule_id) select o.id from ordered o join target t on t.grp=o.grp)) then return jsonb_build_object('ok',false,'error','BLOCK_WOULD_MERGE');end if;with ordered as(select ts.id,ts.period,ts.classroom_id,ts.period-row_number() over(order by ts.period)::integer grp from public.teacher_schedule ts where ts.active and ts.institution_code=public.current_tenant_code() and ts.teacher_assignment_id=r.teacher_assignment_id and ts.weekday=r.weekday),target as(select grp from ordered where id=p_schedule_id),component as(select o.* from ordered o join target t on t.grp=o.grp) select jsonb_agg(jsonb_build_object('schedule_id',c.id,'weekday',p_weekday,'period',v_target_start+(c.period-v_start),'classroom_id',coalesce(p_classroom_id,c.classroom_id)) order by c.period) into v_moves from component c;return jsonb_build_object('ok',true,'block',true,'assignment_id',r.teacher_assignment_id,'duration',v_len,'source_start',v_start,'target_start',v_target_start,'moves',v_moves);end$$;
create or replace function public.get_schedule_atomic_move_plan_v1(p_schedule_id uuid,p_weekday smallint,p_period smallint,p_classroom_id uuid default null) returns jsonb language plpgsql security definer set search_path=public as $$declare r public.teacher_schedule%rowtype;p jsonb;begin perform public.open_permission_context('schedule.edit');select * into r from public.teacher_schedule where id=p_schedule_id and active and institution_code=public.current_tenant_code();if not found then return jsonb_build_object('ok',false,'error','SCHEDULE_ROW_NOT_FOUND');end if;if r.locked then return jsonb_build_object('ok',false,'error','SCHEDULE_ROW_LOCKED');end if;p:=public.get_schedule_block_move_plan_v1(p_schedule_id,p_weekday,p_period,p_classroom_id);if coalesce((p->>'ok')::boolean,false) then return p;end if;if p->>'error'<>'NOT_BLOCK_ACTIVITY' then return p;end if;return jsonb_build_object('ok',true,'block',false,'assignment_id',r.teacher_assignment_id,'duration',1,'moves',jsonb_build_array(jsonb_build_object('schedule_id',r.id,'weekday',p_weekday,'period',p_period,'classroom_id',coalesce(p_classroom_id,r.classroom_id))));end$$;
create or replace function public.preview_schedule_move_v1(p_schedule_id uuid,p_weekday smallint,p_period smallint,p_classroom_id uuid default null) returns jsonb language plpgsql security definer set search_path=public as $$declare p jsonb;q jsonb;begin p:=public.get_schedule_atomic_move_plan_v1(p_schedule_id,p_weekday,p_period,p_classroom_id);if not coalesce((p->>'ok')::boolean,false) then return p;end if;q:=public.preview_schedule_batch_move_v1(p->'moves');return q||jsonb_build_object('block',coalesce((p->>'block')::boolean,false),'duration',(p->>'duration')::int);end$$;
create or replace function public.move_schedule_slot_v1(p_schedule_id uuid,p_weekday smallint,p_period smallint,p_classroom_id uuid default null) returns uuid language plpgsql security definer set search_path=public as $$declare p jsonb;q jsonb;aid uuid;begin p:=public.get_schedule_atomic_move_plan_v1(p_schedule_id,p_weekday,p_period,p_classroom_id);if not coalesce((p->>'ok')::boolean,false) then raise exception '%',coalesce(p->>'error','MOVE_INVALID');end if;aid:=nullif(p->>'assignment_id','')::uuid;q:=public.move_schedule_slots_batch_v1(p->'moves');if coalesce((p->>'block')::boolean,false) and not public.schedule_current_block_matches_phase3_v1(aid) then raise exception 'BLOCK_PATTERN_BROKEN';end if;return p_schedule_id;end$$;
create or replace function public.preview_schedule_swap_v1(p_left_id uuid,p_right_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare a public.teacher_schedule%rowtype;b public.teacher_schedule%rowtype;lp jsonb;rp jsonb;moves jsonb;begin perform public.open_permission_context('schedule.edit');if p_left_id=p_right_id then return jsonb_build_object('ok',false,'error','SAME_SCHEDULE_ROW');end if;select * into a from public.teacher_schedule where id=p_left_id and active and institution_code=public.current_tenant_code();select * into b from public.teacher_schedule where id=p_right_id and active and institution_code=public.current_tenant_code();if a.id is null or b.id is null then return jsonb_build_object('ok',false,'error','SCHEDULE_ROW_NOT_FOUND');end if;if a.locked or b.locked then return jsonb_build_object('ok',false,'error','SCHEDULE_ROW_LOCKED');end if;lp:=public.get_schedule_atomic_move_plan_v1(a.id,b.weekday,b.period,a.classroom_id);if not coalesce((lp->>'ok')::boolean,false) then return lp;end if;rp:=public.get_schedule_atomic_move_plan_v1(b.id,a.weekday,a.period,b.classroom_id);if not coalesce((rp->>'ok')::boolean,false) then return rp;end if;moves:=(lp->'moves')||(rp->'moves');return public.preview_schedule_batch_move_v1(moves)||jsonb_build_object('block_swap',coalesce((lp->>'block')::boolean,false) or coalesce((rp->>'block')::boolean,false));end$$;
create or replace function public.swap_schedule_slots_v1(p_left_id uuid,p_right_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare a public.teacher_schedule%rowtype;b public.teacher_schedule%rowtype;lp jsonb;rp jsonb;moves jsonb;q jsonb;laid uuid;raid uuid;begin perform public.open_permission_context('schedule.edit');if p_left_id=p_right_id then raise exception 'SAME_SCHEDULE_ROW';end if;select * into a from public.teacher_schedule where id=p_left_id and active and institution_code=public.current_tenant_code();select * into b from public.teacher_schedule where id=p_right_id and active and institution_code=public.current_tenant_code();if a.id is null or b.id is null then raise exception 'SCHEDULE_ROW_NOT_FOUND';end if;if a.locked or b.locked then raise exception 'SCHEDULE_ROW_LOCKED';end if;lp:=public.get_schedule_atomic_move_plan_v1(a.id,b.weekday,b.period,a.classroom_id);rp:=public.get_schedule_atomic_move_plan_v1(b.id,a.weekday,a.period,b.classroom_id);if not coalesce((lp->>'ok')::boolean,false) then raise exception '%',lp->>'error';end if;if not coalesce((rp->>'ok')::boolean,false) then raise exception '%',rp->>'error';end if;moves:=(lp->'moves')||(rp->'moves');q:=public.move_schedule_slots_batch_v1(moves);laid:=nullif(lp->>'assignment_id','')::uuid;raid:=nullif(rp->>'assignment_id','')::uuid;if coalesce((lp->>'block')::boolean,false) and not public.schedule_current_block_matches_phase3_v1(laid) then raise exception 'BLOCK_PATTERN_BROKEN';end if;if coalesce((rp->>'block')::boolean,false) and not public.schedule_current_block_matches_phase3_v1(raid) then raise exception 'BLOCK_PATTERN_BROKEN';end if;return q||jsonb_build_object('block_swap',coalesce((lp->>'block')::boolean,false) or coalesce((rp->>'block')::boolean,false));end$$;
revoke all on function public.get_schedule_atomic_move_plan_v1(uuid,smallint,smallint,uuid) from public;grant execute on function public.get_schedule_atomic_move_plan_v1(uuid,smallint,smallint,uuid) to authenticated;
